/* ---------- TEORÍA ---------- */
const THEORY = {
rai:[
 {h:{es:'Los seis principios',en:'The six principles'},b:[
  {es:'<b>Fairness (equidad)</b>: el sistema trata a todas las personas por igual. Riesgo típico: sesgo en los datos de entrenamiento (p. ej. un modelo de concesión de créditos que penaliza a un grupo). Mitigación: datos representativos, evaluar resultados por subgrupos.',en:'<b>Fairness</b>: the system treats all people equally. Typical risk: bias in training data (e.g. a loan model that penalises a group). Mitigation: representative data, evaluate results by subgroup.'},
  {es:'<b>Reliability and safety (fiabilidad y seguridad)</b>: funciona como se espera y falla de forma segura. Pruebas rigurosas, gestión de casos límite, umbrales de confianza y monitorización en producción.',en:'<b>Reliability and safety</b>: works as expected and fails safely. Rigorous testing, edge-case handling, confidence thresholds and production monitoring.'},
  {es:'<b>Privacy and security (privacidad y seguridad)</b>: protege los datos personales usados en entrenamiento y en inferencia. Consentimiento, minimización de datos, cifrado y control de acceso.',en:'<b>Privacy and security</b>: protects personal data used in training and inference. Consent, data minimisation, encryption and access control.'},
  {es:'<b>Inclusiveness (inclusión)</b>: empodera a todas las personas, incluidas las que tienen discapacidad. Diseño accesible: voz para quien no puede leer, subtítulos para quien no oye.',en:'<b>Inclusiveness</b>: empowers everyone, including people with disabilities. Accessible design: speech for those who cannot read, captions for those who cannot hear.'},
  {es:'<b>Transparency (transparencia)</b>: los usuarios entienden cómo funciona el sistema, sus límites y que interactúan con una IA. Ej.: indicar que un texto lo ha generado IA, documentar con <i>transparency notes</i>.',en:'<b>Transparency</b>: users understand how the system works, its limitations and that they are interacting with AI. E.g. disclose AI-generated content, document with transparency notes.'},
  {es:'<b>Accountability (responsabilidad)</b>: las personas que diseñan y despliegan el sistema responden de él. Gobernanza, supervisión humana y marcos de cumplimiento.',en:'<b>Accountability</b>: the people who design and deploy the system are answerable for it. Governance, human oversight and compliance frameworks.'}
 ]},
 {h:{es:'Cómo se aplica en Foundry',en:'How it applies in Foundry'},b:[
  {es:'<b>Filtros de contenido (guardrails)</b>: por defecto filtran odio, contenido sexual, violencia y autolesiones en entradas y salidas, con niveles de severidad configurables.',en:'<b>Content filters (guardrails)</b>: by default they filter hate, sexual, violence and self-harm in inputs and outputs, with configurable severity levels.'},
  {es:'<b>Prompt Shields</b>: detectan ataques de jailbreak y prompt injection (también indirectos, ocultos en documentos).',en:'<b>Prompt Shields</b>: detect jailbreak and prompt-injection attacks (including indirect ones hidden in documents).'},
  {es:'<b>Evaluaciones</b>: miden calidad (groundedness, relevancia, coherencia) y riesgos de seguridad antes de pasar a producción.',en:'<b>Evaluations</b>: measure quality (groundedness, relevance, coherence) and safety risks before going to production.'},
  {es:'Truco de examen: identifica el principio por la <b>palabra clave del escenario</b>: "sesgo/grupo" → fairness; "discapacidad" → inclusiveness; "explicar/avisar de que es IA" → transparency; "datos personales" → privacy; "quién responde" → accountability; "fallos/condiciones inesperadas" → reliability.',en:'Exam tip: identify the principle by the <b>scenario keyword</b>: "bias/group" → fairness; "disability" → inclusiveness; "explain/disclose it is AI" → transparency; "personal data" → privacy; "who is answerable" → accountability; "failures/unexpected conditions" → reliability.'}
 ]}
],
models:[
 {h:{es:'Cómo funcionan los modelos generativos',en:'How generative models work'},b:[
  {es:'Los LLM se basan en la arquitectura <b>Transformer</b>. El texto se divide en <b>tokens</b>, cada token se convierte en un <b>embedding</b> (vector numérico que captura su significado) y el mecanismo de <b>atención</b> pondera la relación entre tokens.',en:'LLMs are based on the <b>Transformer</b> architecture. Text is split into <b>tokens</b>, each token becomes an <b>embedding</b> (a numeric vector that captures meaning) and the <b>attention</b> mechanism weighs relationships between tokens.'},
  {es:'El modelo genera texto <b>prediciendo el siguiente token</b> más probable, una y otra vez. Por eso puede "alucinar": produce texto plausible aunque no sea cierto.',en:'The model generates text by <b>predicting the next most likely token</b>, again and again. That is why it can "hallucinate": it produces plausible text even when it is not true.'},
  {es:'<b>Grounding / RAG</b> (Retrieval-Augmented Generation): se recuperan datos relevantes (p. ej. con búsqueda vectorial) y se añaden al prompt para que la respuesta se base en información real.',en:'<b>Grounding / RAG</b> (Retrieval-Augmented Generation): relevant data is retrieved (e.g. via vector search) and added to the prompt so the answer is based on real information.'},
  {es:'La <b>ventana de contexto</b> es el número máximo de tokens (prompt + respuesta) que el modelo puede manejar en una petición.',en:'The <b>context window</b> is the maximum number of tokens (prompt + completion) the model can handle in a request.'}
 ]},
 {h:{es:'Elegir el modelo adecuado',en:'Choosing the right model'},b:[
  {es:'<b>LLM de chat</b> (familia GPT): conversación, redacción, resumen, razonamiento general.',en:'<b>Chat LLMs</b> (GPT family): conversation, writing, summarisation, general reasoning.'},
  {es:'<b>Modelos de razonamiento</b>: problemas complejos de varios pasos (matemáticas, código). Más lentos y caros.',en:'<b>Reasoning models</b>: complex multi-step problems (maths, code). Slower and more expensive.'},
  {es:'<b>Modelos multimodales</b>: aceptan imagen y/o audio además de texto (describir una foto, responder a una pregunta hablada).',en:'<b>Multimodal models</b>: accept image and/or audio as well as text (describe a photo, answer a spoken question).'},
  {es:'<b>Small Language Models (SLM)</b>, p. ej. Phi: baratos, rápidos, pueden ejecutarse en el borde; ideales para tareas acotadas.',en:'<b>Small Language Models (SLM)</b>, e.g. Phi: cheap, fast, can run at the edge; ideal for narrow tasks.'},
  {es:'<b>Modelos de embeddings</b> (text-embedding-3-…): convierten texto en vectores para búsqueda semántica y RAG. No generan texto.',en:'<b>Embedding models</b> (text-embedding-3-…): turn text into vectors for semantic search and RAG. They do not generate text.'},
  {es:'<b>Modelos de imagen</b> (gpt-image-1, DALL·E): generan o editan imágenes a partir de texto.',en:'<b>Image models</b> (gpt-image-1, DALL·E): generate or edit images from text.'},
  {es:'En el <b>catálogo de modelos de Foundry</b> puedes comparar modelos con <i>benchmarks</i> y <i>leaderboards</i> (calidad, coste, latencia) y probarlos en el playground.',en:'In the <b>Foundry model catalog</b> you can compare models with benchmarks and leaderboards (quality, cost, latency) and try them in the playground.'}
 ]},
 {h:{es:'Despliegue y parámetros',en:'Deployment and parameters'},b:[
  {es:'Para usar un modelo hay que crear un <b>deployment</b> con nombre; en el código se pasa ese <b>nombre de despliegue</b>, no el nombre del modelo.',en:'To use a model you create a named <b>deployment</b>; in code you pass that <b>deployment name</b>, not the model name.'},
  {es:'Tipos de despliegue: <b>Standard / Global Standard</b> (pago por token, compartido), <b>Data Zone</b> (procesamiento dentro de una zona geográfica, p. ej. UE), <b>Provisioned (PTU)</b> (capacidad reservada, latencia predecible para cargas altas y estables) y <b>Batch</b> (peticiones asíncronas masivas, más baratas, sin tiempo real).',en:'Deployment types: <b>Standard / Global Standard</b> (pay per token, shared), <b>Data Zone</b> (processing within a geography, e.g. EU), <b>Provisioned (PTU)</b> (reserved capacity, predictable latency for high steady loads) and <b>Batch</b> (large asynchronous jobs, cheaper, not real-time).'},
  {es:'<b>Temperature</b>: aleatoriedad. Baja (0–0,3) = respuestas deterministas y precisas; alta (0,8+) = creatividad. <b>Top P</b>: muestreo por probabilidad acumulada; se recomienda ajustar uno de los dos, no ambos.',en:'<b>Temperature</b>: randomness. Low (0–0.3) = deterministic, precise answers; high (0.8+) = creativity. <b>Top P</b>: cumulative-probability sampling; adjust one or the other, not both.'},
  {es:'<b>Max tokens</b>: límite de longitud de la respuesta. <b>Stop sequences</b>: cadenas que cortan la generación. <b>Frequency/Presence penalty</b>: reducen repeticiones o fomentan temas nuevos.',en:'<b>Max tokens</b>: limit on response length. <b>Stop sequences</b>: strings that end generation. <b>Frequency/Presence penalty</b>: reduce repetition or encourage new topics.'},
  {es:'Límites de cuota: se miden en <b>TPM</b> (tokens por minuto) y <b>RPM</b> (peticiones por minuto) por despliegue.',en:'Quota limits are measured in <b>TPM</b> (tokens per minute) and <b>RPM</b> (requests per minute) per deployment.'}
 ]}
],
workloads:[
 {h:{es:'Escenarios por tipo de carga',en:'Scenarios by workload'},b:[
  {es:'<b>IA generativa</b>: crea contenido nuevo (texto, código, imágenes) a partir de un prompt. <b>IA agéntica</b>: un modelo que razona, decide y usa herramientas para completar tareas por su cuenta.',en:'<b>Generative AI</b>: creates new content (text, code, images) from a prompt. <b>Agentic AI</b>: a model that reasons, decides and uses tools to complete tasks on its own.'},
  {es:'<b>Análisis de texto (NLP)</b>: entender texto existente. <b>Voz</b>: convertir voz↔texto. <b>Visión</b>: interpretar imágenes y vídeo. <b>Extracción de información</b>: sacar datos estructurados de documentos, imágenes, audio y vídeo.',en:'<b>Text analysis (NLP)</b>: understand existing text. <b>Speech</b>: convert speech↔text. <b>Vision</b>: interpret images and video. <b>Information extraction</b>: pull structured data from documents, images, audio and video.'}
 ]},
 {h:{es:'Técnicas de análisis de texto',en:'Text analysis techniques'},b:[
  {es:'<b>Key phrase extraction</b>: los puntos principales ("menú degustación", "servicio lento").',en:'<b>Key phrase extraction</b>: the main talking points ("tasting menu", "slow service").'},
  {es:'<b>Named Entity Recognition (NER)</b>: personas, lugares, organizaciones, fechas, cantidades. <b>Entity linking</b> enlaza la entidad con Wikipedia. <b>Detección de PII</b>: localiza y oculta datos personales.',en:'<b>Named Entity Recognition (NER)</b>: people, places, organisations, dates, quantities. <b>Entity linking</b> links the entity to Wikipedia. <b>PII detection</b>: finds and redacts personal data.'},
  {es:'<b>Sentiment analysis</b>: positivo / negativo / neutro / mixto con puntuación de confianza; <i>opinion mining</i> lo hace por aspecto.',en:'<b>Sentiment analysis</b>: positive / negative / neutral / mixed with confidence scores; opinion mining does it per aspect.'},
  {es:'<b>Summarization</b>: <i>extractiva</i> (selecciona frases del original) o <i>abstractiva</i> (redacta un resumen nuevo). <b>Language detection</b>: idioma y puntuación.',en:'<b>Summarization</b>: extractive (selects sentences from the original) or abstractive (writes a new summary). <b>Language detection</b>: language and score.'}
 ]},
 {h:{es:'Voz',en:'Speech'},b:[
  {es:'<b>Speech recognition (speech-to-text)</b>: transcribe audio a texto, en tiempo real o por lotes. Admite <i>diarización</i> (quién habla) y modelos personalizados para vocabulario específico.',en:'<b>Speech recognition (speech-to-text)</b>: transcribes audio to text, real-time or batch. Supports diarization (who is speaking) and custom models for domain vocabulary.'},
  {es:'<b>Speech synthesis (text-to-speech)</b>: genera audio a partir de texto con <b>voces neuronales</b>. <b>SSML</b> controla pronunciación, pausas, velocidad, tono y estilo.',en:'<b>Speech synthesis (text-to-speech)</b>: generates audio from text with <b>neural voices</b>. <b>SSML</b> controls pronunciation, pauses, rate, pitch and style.'},
  {es:'<b>Speech translation</b>: traduce voz a texto o voz en otro idioma.',en:'<b>Speech translation</b>: translates speech into text or speech in another language.'}
 ]},
 {h:{es:'Visión',en:'Vision'},b:[
  {es:'<b>Clasificación de imágenes</b>: ¿qué hay en la imagen? (una etiqueta). <b>Detección de objetos</b>: qué y <b>dónde</b> (bounding boxes). <b>Segmentación semántica</b>: clasifica cada píxel.',en:'<b>Image classification</b>: what is in the image (one label). <b>Object detection</b>: what and <b>where</b> (bounding boxes). <b>Semantic segmentation</b>: classifies every pixel.'},
  {es:'<b>OCR</b>: lee texto impreso o manuscrito. <b>Captioning/tagging</b>: describe la imagen. <b>Análisis facial</b>: detecta caras y atributos; la identificación está restringida (Limited Access) por IA responsable.',en:'<b>OCR</b>: reads printed or handwritten text. <b>Captioning/tagging</b>: describes the image. <b>Face analysis</b>: detects faces and attributes; identification is restricted (Limited Access) for responsible AI.'},
  {es:'Las CNN extraen características visuales; los modelos multimodales modernos combinan un codificador de imagen con un LLM. Los modelos de <b>generación de imágenes</b> (difusión) crean imágenes nuevas desde texto.',en:'CNNs extract visual features; modern multimodal models combine an image encoder with an LLM. <b>Image-generation</b> models (diffusion) create new images from text.'}
 ]},
 {h:{es:'Extracción de información',en:'Information extraction'},b:[
  {es:'Documentos y formularios: OCR + layout (tablas, párrafos) + campos (pares clave-valor: número de factura, total, fecha).',en:'Documents and forms: OCR + layout (tables, paragraphs) + fields (key-value pairs: invoice number, total, date).'},
  {es:'Audio y vídeo: transcripción, resumen, temas, sentimiento; en vídeo además segmentación en escenas y descripción de lo que aparece.',en:'Audio and video: transcription, summary, topics, sentiment; for video also scene segmentation and descriptions of what appears.'}
 ]}
],
genai:[
 {h:{es:'Prompts eficaces',en:'Effective prompts'},b:[
  {es:'<b>System prompt</b> (rol <code>system</code>): define el comportamiento global: persona, tono, límites, formato de salida, qué hacer si no sabe. <b>User prompt</b> (rol <code>user</code>): la petición concreta. El rol <code>assistant</code> guarda las respuestas previas (historial).',en:'<b>System prompt</b> (<code>system</code> role): defines overall behaviour: persona, tone, limits, output format, what to do when unsure. <b>User prompt</b> (<code>user</code> role): the specific request. The <code>assistant</code> role holds previous replies (history).'},
  {es:'Buenas prácticas: instrucciones claras y específicas, indicar el <b>formato</b> (JSON, tabla, viñetas), dar <b>contexto/datos</b> (grounding), incluir <b>ejemplos</b> (<i>few-shot</i>), dividir tareas complejas en pasos y usar delimitadores.',en:'Good practice: clear, specific instructions, state the <b>format</b> (JSON, table, bullets), provide <b>context/data</b> (grounding), include <b>examples</b> (few-shot), break complex tasks into steps and use delimiters.'},
  {es:'<b>Zero-shot</b>: sin ejemplos. <b>Few-shot</b>: con varios ejemplos de entrada/salida para fijar el patrón.',en:'<b>Zero-shot</b>: no examples. <b>Few-shot</b>: several input/output examples to set the pattern.'}
 ]},
 {h:{es:'Foundry: recursos y portal',en:'Foundry: resources and portal'},b:[
  {es:'Un <b>recurso de Microsoft Foundry</b> contiene uno o varios <b>proyectos</b>. El proyecto agrupa despliegues, agentes, conexiones y evaluaciones. El endpoint del proyecto tiene la forma <code>https://&lt;recurso&gt;.services.ai.azure.com/api/projects/&lt;proyecto&gt;</code>.',en:'A <b>Microsoft Foundry resource</b> contains one or more <b>projects</b>. The project groups deployments, agents, connections and evaluations. The project endpoint looks like <code>https://&lt;resource&gt;.services.ai.azure.com/api/projects/&lt;project&gt;</code>.'},
  {es:'Flujo en el portal: catálogo de modelos → <b>Deploy</b> → probar en el <b>Chat playground</b> (ajustar system prompt y parámetros) → <b>View code</b> para obtener el ejemplo de código.',en:'Portal flow: model catalog → <b>Deploy</b> → test in the <b>Chat playground</b> (tweak system prompt and parameters) → <b>View code</b> to get sample code.'}
 ]},
 {h:{es:'Cliente de chat con el SDK de Foundry',en:'Chat client with the Foundry SDK'},code:`# pip install azure-ai-projects azure-identity openai
from azure.identity import DefaultAzureCredential
from azure.ai.projects import AIProjectClient

project = AIProjectClient(
    endpoint="https://<resource>.services.ai.azure.com/api/projects/<project>",
    credential=DefaultAzureCredential())

chat = project.get_openai_client()          # cliente OpenAI autenticado

messages = [{"role": "system", "content": "Eres un asistente de viajes."}]
while True:
    messages.append({"role": "user", "content": input("> ")})
    resp = chat.chat.completions.create(
        model="my-gpt-deployment",           # NOMBRE DEL DESPLIEGUE
        messages=messages, temperature=0.3)
    answer = resp.choices[0].message.content
    messages.append({"role": "assistant", "content": answer})  # historial
    print(answer)`,b:[
  {es:'<code>DefaultAzureCredential</code> autentica con Microsoft Entra ID (tu sesión de <code>az login</code>, identidad administrada…), sin claves en el código.',en:'<code>DefaultAzureCredential</code> authenticates with Microsoft Entra ID (your <code>az login</code> session, managed identity…) with no keys in code.'},
  {es:'El cliente obtenido con <code>get_openai_client()</code> sirve para <b>cualquier modelo</b> desplegado en el recurso, incluso no-OpenAI como Phi. Cambias de modelo cambiando el nombre del despliegue.',en:'The client from <code>get_openai_client()</code> works with <b>any model</b> deployed in the resource, even non-OpenAI ones like Phi. You switch models by changing the deployment name.'},
  {es:'El modelo no tiene memoria: para mantener la conversación hay que reenviar el historial completo en <code>messages</code>.',en:'The model is stateless: to keep a conversation you resend the full history in <code>messages</code>.'}
 ]},
 {h:{es:'Agentes con Foundry Agent Service',en:'Agents with Foundry Agent Service'},b:[
  {es:'Un agente = <b>modelo</b> + <b>instrucciones</b> + <b>herramientas</b>. Se crea y prueba en el portal (Agents → playground) o por código.',en:'An agent = <b>model</b> + <b>instructions</b> + <b>tools</b>. Created and tested in the portal (Agents → playground) or in code.'},
  {es:'Herramientas de conocimiento: <b>File search</b> (RAG sobre archivos subidos, almacén vectorial), <b>Azure AI Search</b>, <b>Grounding with Bing / Web search</b> (datos actuales de la web), SharePoint.',en:'Knowledge tools: <b>File search</b> (RAG over uploaded files, vector store), <b>Azure AI Search</b>, <b>Grounding with Bing / Web search</b> (current web data), SharePoint.'},
  {es:'Herramientas de acción: <b>Code interpreter</b> (ejecuta Python en un sandbox: cálculos, gráficos, procesar CSV), <b>Function calling</b> (tus funciones), <b>OpenAPI</b> (APIs externas), <b>MCP</b>.',en:'Action tools: <b>Code interpreter</b> (runs Python in a sandbox: calculations, charts, CSV processing), <b>Function calling</b> (your functions), <b>OpenAPI</b> (external APIs), <b>MCP</b>.'},
  {es:'La conversación vive en un <b>hilo / conversation</b> con estado que guarda el historial; cada ejecución del agente sobre él (<b>run</b> / respuesta) decide qué herramientas usar y genera la respuesta.',en:'The conversation lives in a stateful <b>thread / conversation</b> that keeps history; each agent execution on it (<b>run</b> / response) decides which tools to call and produces the answer.'}
 ],code2:`# Cliente ligero para un agente existente (patrón general)
agent = project.agents.get_agent(agent_id)           # o create_agent(...)
thread = project.agents.threads.create()
project.agents.messages.create(thread_id=thread.id, role="user",
                               content="¿Cuántas ventas hubo en marzo?")
run = project.agents.runs.create_and_process(thread_id=thread.id,
                                             agent_id=agent.id)
for m in project.agents.messages.list(thread_id=thread.id):
    print(m.role, m.content)`}
],
textspeech:[
 {h:{es:'Análisis de texto con Azure Language',en:'Text analysis with Azure Language'},code:`# pip install azure-ai-textanalytics
from azure.ai.textanalytics import TextAnalyticsClient
from azure.core.credentials import AzureKeyCredential

client = TextAnalyticsClient(endpoint, AzureKeyCredential(key))
docs = ["El hotel era precioso pero el check-in fue lentísimo."]

print(client.detect_language(docs)[0].primary_language.name)
print(client.analyze_sentiment(docs)[0].sentiment)        # mixed
print(client.extract_key_phrases(docs)[0].key_phrases)
for e in client.recognize_entities(docs)[0].entities:
    print(e.text, e.category, e.confidence_score)`,b:[
  {es:'También puedes hacer análisis de texto con un <b>LLM y un buen prompt</b> ("Devuelve el sentimiento y las entidades en JSON"). Azure Language da resultados estructurados y deterministas con puntuación de confianza.',en:'You can also do text analysis with an <b>LLM and a good prompt</b> ("Return sentiment and entities as JSON"). Azure Language gives structured, deterministic results with confidence scores.'}
 ]},
 {h:{es:'Prompts hablados con un modelo multimodal',en:'Spoken prompts with a multimodal model'},b:[
  {es:'Un modelo con entrada de audio (p. ej. gpt-4o con audio) recibe el audio dentro del mensaje como una parte de contenido de tipo <code>input_audio</code> (codificado en base64 con su formato) y responde en texto o audio, sin pasar antes por un servicio de transcripción.',en:'A model with audio input (e.g. gpt-4o with audio) receives the audio inside the message as an <code>input_audio</code> content part (base64-encoded with its format) and answers in text or audio, without a separate transcription service.'}
 ],code:`messages=[{"role":"user","content":[
   {"type":"text","text":"Responde a la pregunta del audio"},
   {"type":"input_audio","input_audio":{"data": audio_b64, "format":"wav"}}]}]`},
 {h:{es:'Azure Speech en Foundry Tools',en:'Azure Speech in Foundry Tools'},code:`# pip install azure-cognitiveservices-speech
import azure.cognitiveservices.speech as speechsdk

cfg = speechsdk.SpeechConfig(subscription=key, region=region)
cfg.speech_recognition_language = "es-ES"
cfg.speech_synthesis_voice_name = "es-ES-ElviraNeural"

# Speech-to-text (micrófono por defecto)
rec = speechsdk.SpeechRecognizer(speech_config=cfg)
result = rec.recognize_once_async().get()
if result.reason == speechsdk.ResultReason.RecognizedSpeech:
    print(result.text)

# Text-to-speech (altavoz por defecto)
synth = speechsdk.SpeechSynthesizer(speech_config=cfg)
synth.speak_text_async("Hola, ¿en qué te ayudo?").get()
# synth.speak_ssml_async(ssml) para controlar estilo, pausas y velocidad`,b:[
  {es:'<code>SpeechConfig</code> lleva credenciales, idioma y voz. <code>AudioConfig</code> elige la fuente/destino (micrófono, archivo WAV, altavoz).',en:'<code>SpeechConfig</code> holds credentials, language and voice. <code>AudioConfig</code> chooses source/target (microphone, WAV file, speaker).'},
  {es:'<code>recognize_once_async</code> reconoce una frase; para audio largo se usa <b>reconocimiento continuo</b> o <b>transcripción por lotes</b>.',en:'<code>recognize_once_async</code> recognises a single utterance; for long audio use <b>continuous recognition</b> or <b>batch transcription</b>.'}
 ]}
],
vision:[
 {h:{es:'Entrada visual en prompts',en:'Visual input in prompts'},code:`resp = chat.chat.completions.create(
  model="my-gpt-4o-deployment",
  messages=[{"role":"user","content":[
     {"type":"text","text":"¿Qué productos hay en esta estantería?"},
     {"type":"image_url","image_url":{"url":"https://.../shelf.jpg"}}
     # o "data:image/jpeg;base64,..." para una imagen local
  ]}])`,b:[
  {es:'Con un <b>modelo multimodal</b> desplegado, el contenido del mensaje es una <b>lista de partes</b>: texto + imagen (URL o data URL en base64). El modelo describe, compara, lee texto de la imagen o responde preguntas sobre ella.',en:'With a deployed <b>multimodal model</b>, the message content is a <b>list of parts</b>: text + image (URL or base64 data URL). The model describes, compares, reads text in the image or answers questions about it.'},
  {es:'En el playground puedes adjuntar una imagen al chat para probarlo sin código.',en:'In the playground you can attach an image to the chat to test it without code.'}
 ]},
 {h:{es:'Generación de imágenes',en:'Image generation'},code:`img = chat.images.generate(
    model="my-gpt-image-deployment",
    prompt="Logo minimalista de una cafetería, estilo acuarela",
    size="1024x1024", n=1)
# respuesta: URL o base64 de la imagen generada`,b:[
  {es:'Los modelos de imagen (gpt-image-1, DALL·E 3) crean imágenes nuevas a partir de un prompt descriptivo. Parámetros típicos: <b>size</b>, <b>quality</b>, <b>n</b> y en algunos modelos estilo. gpt-image-1 también <b>edita</b> imágenes existentes.',en:'Image models (gpt-image-1, DALL·E 3) create new images from a descriptive prompt. Typical parameters: <b>size</b>, <b>quality</b>, <b>n</b> and on some models style. gpt-image-1 can also <b>edit</b> existing images.'},
  {es:'Los filtros de contenido también se aplican a prompts e imágenes generadas.',en:'Content filters also apply to image prompts and generated images.'},
  {es:'Recuerda la diferencia: <b>interpretar</b> una imagen = modelo multimodal (entrada visual); <b>crear</b> una imagen = modelo generativo de imágenes (salida visual).',en:'Remember the difference: <b>interpreting</b> an image = multimodal model (visual input); <b>creating</b> an image = image-generation model (visual output).'}
 ]},
 {h:{es:'App ligera con visión',en:'Lightweight vision app'},b:[
  {es:'Patrón: el usuario sube una foto → la app la codifica en base64 → la envía con un prompt al modelo multimodal → muestra la respuesta. Para devolver datos estructurados pide JSON en el system prompt.',en:'Pattern: the user uploads a photo → the app base64-encodes it → sends it with a prompt to the multimodal model → shows the answer. To return structured data, ask for JSON in the system prompt.'},
  {es:'Si necesitas OCR preciso de documentos o coordenadas exactas de campos, la herramienta adecuada es <b>Content Understanding</b>, no un prompt al LLM.',en:'If you need precise document OCR or exact field coordinates, the right tool is <b>Content Understanding</b>, not an LLM prompt.'}
 ]}
],
extraction:[
 {h:{es:'Qué es Azure Content Understanding',en:'What Azure Content Understanding is'},b:[
  {es:'Servicio de Foundry Tools que extrae información <b>estructurada</b> de <b>documentos, imágenes, audio y vídeo</b> usando IA generativa. Sustituye en muchos escenarios a combinar a mano OCR + Speech + LLM.',en:'Foundry Tools service that extracts <b>structured</b> information from <b>documents, images, audio and video</b> using generative AI. In many scenarios it replaces hand-combining OCR + Speech + LLM.'},
  {es:'La unidad central es el <b>analizador (analyzer)</b>: define qué tipo de contenido procesa, qué extrae (texto, layout, tablas, transcripción, <b>campos</b>) y el formato de salida (markdown + JSON de campos).',en:'The core unit is the <b>analyzer</b>: it defines which content type it processes, what it extracts (text, layout, tables, transcript, <b>fields</b>) and the output format (markdown + JSON fields).'}
 ]},
 {h:{es:'Tipos de analizadores',en:'Analyzer types'},b:[
  {es:'<b>Base</b>: <code>prebuilt-document</code>, <code>prebuilt-image</code>, <code>prebuilt-audio</code>, <code>prebuilt-video</code>. Se usan como padre (<code>baseAnalyzerId</code>) al crear un analizador personalizado.',en:'<b>Base</b>: <code>prebuilt-document</code>, <code>prebuilt-image</code>, <code>prebuilt-audio</code>, <code>prebuilt-video</code>. Used as parent (<code>baseAnalyzerId</code>) when creating a custom analyzer.'},
  {es:'<b>Extracción de contenido</b>: <code>prebuilt-read</code> (OCR) y <code>prebuilt-layout</code> (estructura, tablas).',en:'<b>Content extraction</b>: <code>prebuilt-read</code> (OCR) and <code>prebuilt-layout</code> (structure, tables).'},
  {es:'<b>RAG</b>: <code>prebuilt-documentSearch</code>, <code>prebuilt-audioSearch</code>, <code>prebuilt-videoSearch</code>: extraen contenido en markdown y un resumen, optimizado para búsqueda.',en:'<b>RAG</b>: <code>prebuilt-documentSearch</code>, <code>prebuilt-audioSearch</code>, <code>prebuilt-videoSearch</code>: extract content as markdown plus a summary, optimised for search.'},
  {es:'<b>De dominio</b>: <code>prebuilt-invoice</code>, <code>prebuilt-receipt</code>, <code>prebuilt-idDocument</code>, contratos, llamadas de call center…',en:'<b>Domain-specific</b>: <code>prebuilt-invoice</code>, <code>prebuilt-receipt</code>, <code>prebuilt-idDocument</code>, contracts, call-centre recordings…'},
  {es:'<b>Personalizado</b>: defines un <b>esquema de campos</b> (nombre, tipo, descripción) y el método: <i>extract</i> (literal del contenido), <i>generate</i> (lo infiere/redacta el modelo, p. ej. un resumen) o <i>classify</i> (elige entre categorías).',en:'<b>Custom</b>: you define a <b>field schema</b> (name, type, description) and the method: extract (literal from content), generate (inferred/written by the model, e.g. a summary) or classify (choose among categories).'}
 ]},
 {h:{es:'Por modalidad',en:'By modality'},b:[
  {es:'<b>Documentos/formularios</b>: texto, tablas, pares clave-valor, con <b>confianza</b> y <b>grounding</b> (ubicación en la página).',en:'<b>Documents/forms</b>: text, tables, key-value pairs, with <b>confidence</b> and <b>grounding</b> (location on the page).'},
  {es:'<b>Imágenes</b>: descripción y campos (p. ej. tipo de daño en la foto de un coche, presencia de un producto).',en:'<b>Images</b>: description and fields (e.g. type of damage in a car photo, presence of a product).'},
  {es:'<b>Audio</b>: transcripción con diarización, resumen, temas, sentimiento de la llamada.',en:'<b>Audio</b>: transcript with diarization, summary, topics, call sentiment.'},
  {es:'<b>Vídeo</b>: transcripción, fotogramas clave, división en <b>segmentos/escenas</b> con descripción de cada uno.',en:'<b>Video</b>: transcript, key frames, split into <b>segments/scenes</b> with a description of each.'}
 ]},
 {h:{es:'Llamada desde una app',en:'Calling it from an app'},code:`# REST (patrón asíncrono)
POST {endpoint}/contentunderstanding/analyzers/prebuilt-invoice:analyze?api-version=...
Body: {"inputs":[{"url":"https://.../factura.pdf"}]}
→ 202 Accepted + cabecera Operation-Location
GET  {Operation-Location}   # sondear hasta status = "Succeeded"
→ result.contents[0].markdown  y  result.contents[0].fields.InvoiceTotal`,b:[
  {es:'El análisis es <b>asíncrono</b>: envías el archivo (URL o binario) y sondeas el resultado. En Python el SDK simplifica esto con un <i>poller</i> (<code>begin_analyze(...).result()</code>).',en:'Analysis is <b>asynchronous</b>: you submit the file (URL or binary) and poll for the result. In Python the SDK simplifies this with a poller (<code>begin_analyze(...).result()</code>).'},
  {es:'En el portal de Foundry puedes crear el analizador visualmente, subir un ejemplo, definir campos y probar antes de llamarlo desde código.',en:'In the Foundry portal you can create the analyzer visually, upload a sample, define fields and test before calling it from code.'}
 ]}
]
};

